/* AIVIC_FUNCTION_BUNDLE_START owner=formatReportListWithPagination exports=formatReportListWithPagination */
const __aivicBundle_21_formatReportListWithPagination = (() => {
  async function formatReportListWithPagination(input: {
    employees: Array<{
      id: string;
      name: string;
      department_id: string;
      report_status: string;
      submitted_at?: string;
    }>;
    current_page: number;
    display_limit: number;
  }): Promise<PaginationResult> {
    const { employees, current_page, display_limit } = input;
  
    const total_items = employees.length;
    const total_pages = Math.ceil(total_items / display_limit);
  
    const start_index = (current_page - 1) * display_limit;
    const end_index = start_index + display_limit;
  
    const items = employees.slice(start_index, end_index);
    const items_in_page = items.length;
  
    const has_next_page = current_page < total_pages;
    const has_previous_page = current_page > 1;
  
    return {
      current_page,
      total_items,
      total_pages,
      items_in_page,
      items,
      has_next_page,
      has_previous_page,
    };
  }
  return { formatReportListWithPagination };
})();
export const formatReportListWithPagination = __aivicBundle_21_formatReportListWithPagination.formatReportListWithPagination;
