/* AIVIC_FUNCTION_BUNDLE_END owner=detectUnreportedMembers */

/* AIVIC_FUNCTION_BUNDLE_START owner=identifyUnreportedMembers exports=identifyUnreportedMembers */
const __aivicBundle_27_identifyUnreportedMembers = (() => {
  function identifyUnreportedMembers(params: {
    members: Array<{
      userId: string;
      name: string;
      departmentId: string;
      hasReported: boolean;
      reportedAt?: string;
    }>;
    meetingConfig: {
      meetingDate: string;
      meetingTimeUtc: string;
      reportDeadlineUtc: string;
    };
    currentTimeUtc: string;
  }): {
    unreportedCount: number;
    unreportedMembers: Array<{
      userId: string;
      name: string;
      departmentId: string;
      status: string;
      deadline: string;
    }>;
    isMonthEndDate: boolean;
    targetDate: string;
  } {
    const { members, meetingConfig, currentTimeUtc } = params;
  
    // Extract target date from currentTimeUtc (YYYY-MM-DD format)
    const currentDate = new Date(currentTimeUtc);
    const targetDate = currentDate.toISOString().split("T")[0];
  
    // Determine if it's month-end date (31st)
    const dayOfMonth = currentDate.getUTCDate();
    const isMonthEndDate = dayOfMonth === 31;
  
    // Filter unreported members
    const unreportedMembers = members
      .filter((member) => !member.hasReported)
      .map((member) => ({
        userId: member.userId,
        name: member.name,
        departmentId: member.departmentId,
        status: "本日未報告",
        deadline: meetingConfig.reportDeadlineUtc,
      }));
  
    return {
      unreportedCount: unreportedMembers.length,
      unreportedMembers,
      isMonthEndDate,
      targetDate,
    };
  }
  return { identifyUnreportedMembers };
})();
