const __aivicBundle_129_checkPromptLoopTermination = (() => {
  function checkPromptLoopTermination(context: {
    current_time: Date;
    last_prompt_request_time: Date;
    max_wait_time_ms: number;
  }): {
    should_terminate: boolean;
    reason: string;
    elapsed_hours: number;
    max_hours: number;
    log_message: string;
  } {
    const elapsedMs = context.current_time.getTime() - context.last_prompt_request_time.getTime();
    const elapsedHours = Math.round(elapsedMs / (60 * 60 * 1000));
    const maxHours = Math.round(context.max_wait_time_ms / (60 * 60 * 1000));
  
    const isTimeoutExceeded = elapsedMs > context.max_wait_time_ms;
  
    const reason = isTimeoutExceeded ? '待機時間超過' : '待機中';
    const logMessage = isTimeoutExceeded
      ? `催促ループ終了: 待機時間超過 (${elapsedHours}h > ${maxHours}h)`
      : `催促ループ継続中`;
  
    return {
      should_terminate: isTimeoutExceeded,
      reason: reason,
      elapsed_hours: elapsedHours,
      max_hours: maxHours,
      log_message: logMessage,
    };
  }
  return { checkPromptLoopTermination };
})();
